<?php $id=(int)($_GET['id']??0); $h=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT p.*,pm.namapeminjam,u.namauser FROM peminjaman p LEFT JOIN peminjam pm ON pm.idpeminjam=p.idpeminjam LEFT JOIN user u ON u.iduser=p.iduser WHERE p.idpeminjaman=$id")); $q=mysqli_query($koneksi,"SELECT d.*,a.namaalat FROM detilpeminjaman d LEFT JOIN alat a ON a.idalat=d.idalat WHERE d.idpeminjaman=$id"); ?><h2>Detail Peminjaman</h2><p><b>Peminjam:</b> <?=htmlspecialchars($h['namapeminjam']??'-')?></p><p><b>Tanggal:</b> <?=$h['tanggalpinjam']?></p><p><b>Status:</b> <?=$h['status']?></p><table class="table table-bordered"><tr><th>Alat</th><th>Jumlah</th><th>Kondisi</th></tr><?php while($d=mysqli_fetch_assoc($q)): ?><tr><td><?=htmlspecialchars($d['namaalat']??'-')?></td><td><?=$d['jumlahpinjam']?></td><td><?=$d['kondisi']?></td></tr><?php endwhile;?></table>